import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel source (inline extension)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 16
#define TILE_N 16
#define TILE_K 16

// ------------------------------------------------------------------
// Kernel: C = A * B   (all fp16, accumulation in fp32)
// ------------------------------------------------------------------
__global__ void matmul_kernel(const __half* __restrict__ A,
                              const __half* __restrict__ B,
                              __half* __restrict__ C,
                              int M, int N, int K) {
    __shared__ __half As[TILE_M][TILE_K];
    __shared__ __half Bs[TILE_K][TILE_N];

    int row = blockIdx.y * TILE_M + threadIdx.y;   // output row index
    int col = blockIdx.x * TILE_N + threadIdx.x;   // output col index

    float acc = 0.0f;   // fp32 accumulator

    // Loop over tiles of the K dimension
    for (int t = 0; t < (K + TILE_K - 1) / TILE_K; ++t) {
        // Load A tile
        int a_row = row;
        int a_col = t * TILE_K + threadIdx.x;
        if (a_row < M && a_col < K)
            As[threadIdx.y][threadIdx.x] = A[a_row * K + a_col];
        else
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        // Load B tile
        int b_row = t * TILE_K + threadIdx.y;
        int b_col = col;
        if (b_row < K && b_col < N)
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        else
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadIdx.y][k]) *
                   __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// C++ wrapper exposed to Python
// ------------------------------------------------------------------
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "matmul_fp16: inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "matmul_fp16: inputs must be fp16 (torch.float16)");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "matmul_fp16: inputs must be 2‑dimensional");
    TORCH_CHECK(A.size(1) == B.size(0),
                "matmul_fp16: inner dimensions must match");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M);

    matmul_kernel<<<grid, block, 0,
                    at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        static_cast<int>(M),
        static_cast<int>(N),
        static_cast<int>(K));

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16,
          "FP16 matrix multiplication (CUDA, accumulation in fp32)");
}
'''

# ----------------------------------------------------------------------
# Build the inline extension
# ----------------------------------------------------------------------
matmul_ext = load_inline(name='matmul_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['matmul_fp16'],
                         verbose=False)

# ----------------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication using the custom fp16 CUDA kernel.

        Args:
            A: Tensor of shape (M, K), dtype=torch.float16, CUDA.
            B: Tensor of shape (K, N), dtype=torch.float16, CUDA.

        Returns:
            Tensor of shape (M, N), dtype=torch.float16, CUDA.
        """
        return matmul_ext.matmul_fp16(A, B)
